-- The one-line review a client shows after a turn settles (`※ 回顾`).
--
-- It is generated by an auxiliary model call, but it is a durable, replayable
-- fact about a settled turn: a client that reopens the session must show the
-- SAME review, not disappear and regenerate one. It is deliberately NOT a
-- session_messages row — that table is the model's next-request context, and a
-- UI recap must never enter it.
--
-- (session_id, turn_id) is the stable identity: at most one review per turn,
-- so replaying history or retrying the assist call cannot duplicate the row.
CREATE TABLE session_recaps (
    session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE,
    turn_id    TEXT NOT NULL REFERENCES turns(id) ON DELETE CASCADE,
    text       TEXT NOT NULL,
    created_at TEXT NOT NULL,
    PRIMARY KEY (session_id, turn_id)
);

CREATE INDEX idx_session_recaps_session ON session_recaps(session_id, created_at);
